def lst(items):
    return '<ul class="stack-4" style="list-style:none;padding:0">'+''.join(f'<li class="stack-2" style="gap:var(--s-1)"><a href="{A}">{t}</a><span class="t-maly">{d}</span></li>' for t,d in items)+'</ul>'
out=[]
